import java.io.*;
import java.net.*;
import java.util.*;

public class SecureCode {
    public static void main(String[] args) {
        // This code is secure because it validates the URL before processing.
        // It prevents SSRF attacks by restricting allowed protocols and domains.
        String url = "http://example.com";

        // Validate the URL to ensure it is safe to process
        if (!isValidUrl(url)) {
            System.out.println("Invalid or unsafe URL provided.");
            return;
        }

        try {
            // Only allow specific protocols (e.g., http, https)
            if (!url.startsWith("http://") && !url.startsWith("https://")) {
                System.out.println("Only HTTP/HTTPS protocols are allowed.");
                return;
            }

            // Use a safe URL parser that handles edge cases
            URL safeUrl = new URL(url);
            safeUrl.openConnection();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate URL safety
    private static boolean isValidUrl(String urlString) {
        if (urlString == null || urlString.trim().isEmpty()) {
            return false;
        }

        try {
            new URL(urlString);
            return true;
        } catch (MalformedURLException e) {
            return false;
        }
    }
}

